#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <stdint.h>

template <typename scalar_t>
__global__ void depthwise_vertical_kernel(
    const scalar_t* __restrict__ x,
    const scalar_t* __restrict__ weight,
    const scalar_t* __restrict__ bias,
    scalar_t* __restrict__ out,
    int64_t N,
    int64_t C,
    int64_t H,
    int64_t W,
    int64_t K,
    int64_t Ho,
    int64_t Wo,
    int64_t stride,
    int64_t padding,
    int64_t dilation,
    bool has_bias) {
     constexpr int TILE_H = 16;
     constexpr int TILE_W = 64;
     constexpr int OUTPUTS_PER_THREAD = 4;
    extern __shared__ unsigned char shared_storage[];
    scalar_t* shared_tile = reinterpret_cast<scalar_t*>(shared_storage);
    const int64_t oh =
        static_cast<int64_t>(blockIdx.y) * TILE_H + threadIdx.y;
    const int64_t ow0 =
        static_cast<int64_t>(blockIdx.x) * TILE_W +
        static_cast<int64_t>(threadIdx.x) * OUTPUTS_PER_THREAD;
    const int64_t ow1 = ow0 + 1;
    const int64_t ow2 = ow0 + 2;
    const int64_t ow3 = ow0 + 3;
    const int64_t nc = static_cast<int64_t>(blockIdx.z);
    const int64_t n = nc / C;
    const int64_t c = nc % C;
    if (n >= N) {
        return;
    }
    scalar_t acc0 = has_bias ? bias[c] : scalar_t(0);
    scalar_t acc1 = acc0;
    scalar_t acc2 = acc0;
    scalar_t acc3 = acc0;
    if (stride == 1) {
        const int64_t effective_k = dilation * (K - 1) + 1;
        const int64_t smem_h = TILE_H + effective_k - 1;
        const int64_t smem_elems = smem_h * TILE_W;
        const int64_t tid =
            static_cast<int64_t>(threadIdx.y) * (TILE_W / OUTPUTS_PER_THREAD) +
            threadIdx.x;
        const int64_t x0 =
            static_cast<int64_t>(blockIdx.x) * TILE_W - padding;
        const int64_t y0 =
            static_cast<int64_t>(blockIdx.y) * TILE_H - padding;
        const int64_t vector_chunks = smem_elems / 4;
        for (int64_t i = tid; i < vector_chunks;
             i += TILE_H * (TILE_W / OUTPUTS_PER_THREAD)) {
            const int64_t sy = i / (TILE_W / 4);
            const int64_t sx = (i % (TILE_W / 4)) * 4;
            const int64_t iy = y0 + sy;
            const int64_t ix = x0 + sx;
            if (iy >= 0 && iy < H && ix >= 0 && ix + 3 < W &&
                sizeof(scalar_t) == sizeof(float)) {
                const int64_t x_idx = ((n * C + c) * H + iy) * W + ix;
                const auto address = reinterpret_cast<uintptr_t>(x + x_idx);
                if ((address & (alignof(float4) - 1)) == 0) {
                    const float4 value = *reinterpret_cast<const float4*>(x + x_idx);
                    shared_tile[sy * TILE_W + sx] = static_cast<scalar_t>(value.x);
                    shared_tile[sy * TILE_W + sx + 1] = static_cast<scalar_t>(value.y);
                    shared_tile[sy * TILE_W + sx + 2] = static_cast<scalar_t>(value.z);
                    shared_tile[sy * TILE_W + sx + 3] = static_cast<scalar_t>(value.w);
                    continue;
                }
            }
            for (int offset = 0; offset < 4; ++offset) {
                const int64_t current_x = ix + offset;
                scalar_t value = scalar_t(0);
                if (iy >= 0 && iy < H && current_x >= 0 && current_x < W) {
                    const int64_t x_idx = ((n * C + c) * H + iy) * W + current_x;
                    value = x[x_idx];
                }
                shared_tile[sy * TILE_W + sx + offset] = value;
            }
        }
        __syncthreads();
        if (oh < Ho) {
            for (int64_t ky = 0; ky < K; ++ky) {
                const scalar_t w = weight[c * K + ky];
                const int64_t sy =
                    static_cast<int64_t>(threadIdx.y) + ky * dilation;
                const int64_t sx0 =
                    static_cast<int64_t>(threadIdx.x) * OUTPUTS_PER_THREAD;
                acc0 += shared_tile[sy * TILE_W + sx0] * w;
                if (ow1 < Wo) {
                    acc1 += shared_tile[sy * TILE_W + sx0 + 1] * w;
                }
                if (ow2 < Wo) {
                    acc2 += shared_tile[sy * TILE_W + sx0 + 2] * w;
                }
                if (ow3 < Wo) {
                    acc3 += shared_tile[sy * TILE_W + sx0 + 3] * w;
                }
            }
            if (ow0 < Wo) {
                const int64_t out_idx0 =
                    ((n * C + c) * Ho + oh) * Wo + ow0;
                if (sizeof(scalar_t) == sizeof(float) &&
                    ow3 < Wo &&
                    (reinterpret_cast<uintptr_t>(out + out_idx0) &
                     (alignof(float4) - 1)) == 0) {
                    const float4 value = make_float4(
                        static_cast<float>(acc0),
                        static_cast<float>(acc1),
                        static_cast<float>(acc2),
                        static_cast<float>(acc3));
                    *reinterpret_cast<float4*>(out + out_idx0) = value;
                } else {
                    out[out_idx0] = acc0;
                    if (ow1 < Wo) {
                        out[out_idx0 + 1] = acc1;
                    }
                    if (ow2 < Wo) {
                        out[out_idx0 + 2] = acc2;
                    }
                    if (ow3 < Wo) {
                        out[out_idx0 + 3] = acc3;
                    }
                }
            }
        }
        return;
    }
    if (oh >= Ho) {
        return;
    }
    if (ow0 < Wo) {
        const int64_t ix0 = ow0 * stride - padding;
        if (ix0 >= 0 && ix0 < W) {
            for (int64_t ky = 0; ky < K; ++ky) {
                const int64_t iy =
                    oh * stride - padding + ky * dilation;
                if (iy >= 0 && iy < H) {
                    const int64_t x_idx =
                        ((n * C + c) * H + iy) * W + ix0;
                    acc0 += x[x_idx] * weight[c * K + ky];
                }
            }
        }
        const int64_t out_idx0 =
            ((n * C + c) * Ho + oh) * Wo + ow0;
        out[out_idx0] = acc0;
    }
    if (ow1 < Wo) {
        const int64_t ix1 = ow1 * stride - padding;
        if (ix1 >= 0 && ix1 < W) {
            for (int64_t ky = 0; ky < K; ++ky) {
                const int64_t iy =
                    oh * stride - padding + ky * dilation;
                if (iy >= 0 && iy < H) {
                    const int64_t x_idx =
                        ((n * C + c) * H + iy) * W + ix1;
                    acc1 += x[x_idx] * weight[c * K + ky];
                }
            }
        }
    }
    if (ow2 < Wo) {
        const int64_t ix2 = ow2 * stride - padding;
        if (ix2 >= 0 && ix2 < W) {
            for (int64_t ky = 0; ky < K; ++ky) {
                const int64_t iy =
                    oh * stride - padding + ky * dilation;
                if (iy >= 0 && iy < H) {
                    const int64_t x_idx =
                        ((n * C + c) * H + iy) * W + ix2;
                    acc2 += x[x_idx] * weight[c * K + ky];
                }
            }
        }
    }
    if (ow3 < Wo) {
        const int64_t ix3 = ow3 * stride - padding;
        if (ix3 >= 0 && ix3 < W) {
            for (int64_t ky = 0; ky < K; ++ky) {
                const int64_t iy =
                    oh * stride - padding + ky * dilation;
                if (iy >= 0 && iy < H) {
                    const int64_t x_idx =
                        ((n * C + c) * H + iy) * W + ix3;
                    acc3 += x[x_idx] * weight[c * K + ky];
                }
            }
        }
    }
    if (ow0 < Wo) {
        const int64_t out_idx0 =
            ((n * C + c) * Ho + oh) * Wo + ow0;
        if (sizeof(scalar_t) == sizeof(float) &&
            ow3 < Wo &&
            (reinterpret_cast<uintptr_t>(out + out_idx0) &
             (alignof(float4) - 1)) == 0) {
            const float4 value = make_float4(
                static_cast<float>(acc0),
                static_cast<float>(acc1),
                static_cast<float>(acc2),
                static_cast<float>(acc3));
            *reinterpret_cast<float4*>(out + out_idx0) = value;
        } else {
            out[out_idx0] = acc0;
            if (ow1 < Wo) {
                out[out_idx0 + 1] = acc1;
            }
            if (ow2 < Wo) {
                out[out_idx0 + 2] = acc2;
            }
            if (ow3 < Wo) {
                out[out_idx0 + 3] = acc3;
            }
        }
    }
}
torch::Tensor depthwise_vertical_cuda(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    int64_t stride,
    int64_t padding,
    int64_t dilation) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(weight.is_cuda(), "weight must be a CUDA tensor");
    TORCH_CHECK(bias.is_cuda(), "bias must be a CUDA tensor");
    TORCH_CHECK(x.scalar_type() == torch::kFloat32,
                "Only float32 inputs are supported");
    TORCH_CHECK(weight.scalar_type() == torch::kFloat32,
                "Only float32 weights are supported");
    TORCH_CHECK(bias.scalar_type() == torch::kFloat32,
                "Only float32 bias is supported");
    TORCH_CHECK(x.dim() == 4, "x must have shape [N, C, H, W]");
    TORCH_CHECK(weight.dim() == 4, "weight must have shape [C, 1, K, 1]");
    TORCH_CHECK(weight.size(1) == 1 && weight.size(3) == 1,
                "weight must have shape [C, 1, K, 1]");
    TORCH_CHECK(weight.size(0) == x.size(1),
                "weight channel dimension must match x");
    TORCH_CHECK(bias.numel() == 0 || bias.numel() == x.size(1),
                "bias must be empty or have one value per channel");
    TORCH_CHECK(stride > 0, "stride must be positive");
    TORCH_CHECK(dilation > 0, "dilation must be positive");
    TORCH_CHECK(padding >= 0, "padding must be non-negative");

    auto x_c = x.contiguous();
    auto w_c = weight.contiguous();
    auto b_c = bias.contiguous();

    const int64_t N = x_c.size(0);
    const int64_t C = x_c.size(1);
    const int64_t H = x_c.size(2);
    const int64_t W = x_c.size(3);
    const int64_t K = w_c.size(2);

    const int64_t effective_k = dilation * (K - 1) + 1;
    const int64_t Ho = (H + 2 * padding - effective_k) / stride + 1;
    const int64_t Wo = (W + 2 * padding - 1) / stride + 1;

    TORCH_CHECK(Ho >= 0 && Wo >= 0, "Invalid output dimensions");

    auto out = torch::empty({N, C, Ho, Wo}, x_c.options());

    const int64_t total = N * C * Ho * Wo;
    if (total == 0) {
        return out;
    }

     constexpr int TILE_H = 16;
     constexpr int TILE_W = 64;
     const dim3 threads(TILE_W / 4, TILE_H, 1);
    const dim3 blocks(
        static_cast<unsigned int>((Wo + TILE_W - 1) / TILE_W),
        static_cast<unsigned int>((Ho + TILE_H - 1) / TILE_H),
        static_cast<unsigned int>(N * C));
    cudaStream_t stream = at::cuda::getCurrentCUDAStream(x_c.device().index());
    AT_DISPATCH_FLOATING_TYPES(
        x_c.scalar_type(),
        "depthwise_vertical_cuda",
        [&] {
            const size_t smem_bytes =
                stride == 1
                    ? static_cast<size_t>(TILE_W *
                                          (TILE_H + effective_k - 1)) *
                          sizeof(scalar_t)
                    : 0;
            depthwise_vertical_kernel<scalar_t><<<blocks, threads, smem_bytes, stream>>>(
                x_c.data_ptr<scalar_t>(),
                w_c.data_ptr<scalar_t>(),
                b_c.numel() ? b_c.data_ptr<scalar_t>() : nullptr,
                out.data_ptr<scalar_t>(),
                N,
                C,
                H,
                W,
                K,
                Ho,
                Wo,
                stride,
                padding,
                dilation,
                b_c.numel() != 0);
        });

    return out;
}
