_cpp_src = r"""
#include <torch/extension.h>

torch::Tensor depthwise_vertical_cuda(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    int64_t stride,
    int64_t padding,
    int64_t dilation);

torch::Tensor depthwise_vertical(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    int64_t stride,
    int64_t padding,
    int64_t dilation) {
    return depthwise_vertical_cuda(
        x, weight, bias, stride, padding, dilation);
}
"""

_depthwise_ext = load_inline(
    name="depthwise_vertical_cuda_ext",
    cpp_sources=_cpp_src,
    cuda_sources=_cuda_src,
    functions=["depthwise_vertical"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    with_cuda=True,
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(
        self,
        in_channels: int,
        kernel_size: int,
        stride: int = 1,
        padding: int = 0,
        dilation: int = 1,
        bias: bool = False,
    ):
        super().__init__()

        self.conv2d = nn.Conv2d(
            in_channels,
            in_channels,
            kernel_size=(kernel_size, 1),
            stride=stride,
            padding=padding,
            dilation=dilation,
            groups=in_channels,
            bias=bias,
        )

        self.stride = stride
        self.padding = padding
        self.dilation = dilation

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if self.conv2d.bias is None:
            bias = torch.empty(
                0,
                device=x.device,
                dtype=x.dtype,
            )
        else:
            bias = self.conv2d.bias

        return _depthwise_ext.depthwise_vertical(
            x,
            self.conv2d.weight,
            bias,
            self.stride,
            self.padding,
            self.dilation,
        )

